    'every_api_key_sitting_in_an_app_s_config_or__975161a8' => 'Cada clave de API sentada en el archivo de configuración o entorno de una aplicación es una que no se puede rotar de forma centralizada o quitar con prisa. Almacenado aquí, está cifrado, concedido por aplicación, y revocable en un solo clic.',
    'every_api_key_the_people_in_this_organizatio_15e73625' => 'Cada clave de API que la gente en esta organización ha creado para sus aplicaciones. Revoke uno que se filtró o ya no se utiliza. La gente crea sus propias claves bajo Mi cuenta.',
    'every_api_key_the_people_in_this_organizatio_fe7787a7' => 'Cada clave de API que las personas de esta organización han creado para sus aplicaciones: quién la tiene, para qué aplicación es, para qué puede hacer y cuándo se usó por última vez. Una clave sólo puede hacer lo que su titular puede, y deja de funcionar cuando se van. Revoca una que se filtró o ya no se utiliza; cada persona crea sus propias claves bajo Mi cuenta.',
    'every_app_asking_for_this_flag_gets_off_this_e3ed99c1' => 'Cada aplicación que pide esta bandera se apaga. Esto no se puede deshacer.',
